184	/// Decode mac roman encoded bytes into a string.
185	fn decode_mac_roman(coded: &[u8]) -> String {
186	    #[rustfmt::skip]
187	    const TABLE: [char; 128] = [
188	        'Ä', 'Å', 'Ç', 'É', 'Ñ', 'Ö', 'Ü', 'á', 'à', 'â', 'ä', 'ã', 'å', 'ç', 'é', 'è',
189	        'ê', 'ë', 'í', 'ì', 'î', 'ï', 'ñ', 'ó', 'ò', 'ô', 'ö', 'õ', 'ú', 'ù', 'û', 'ü',
190	        '†', '°', '¢', '£', '§', '•', '¶', 'ß', '®', '©', '™', '´', '¨', '≠', 'Æ', 'Ø',
191	        '∞', '±', '≤', '≥', '¥', 'µ', '∂', '∑', '∏', 'π', '∫', 'ª', 'º', 'Ω', 'æ', 'ø',
192	        '¿', '¡', '¬', '√', 'ƒ', '≈', '∆', '«', '»', '…', '\u{a0}', 'À', 'Ã', 'Õ', 'Œ', 'œ',
193	        '–', '—', '“', '”', '‘', '’', '÷', '◊', 'ÿ', 'Ÿ', '⁄', '€', '‹', '›', 'ﬁ', 'ﬂ',
194	        '‡', '·', '‚', '„', '‰', 'Â', 'Ê', 'Á', 'Ë', 'È', 'Í', 'Î', 'Ï', 'Ì', 'Ó', 'Ô',
195	        '\u{f8ff}', 'Ò', 'Ú', 'Û', 'Ù', 'ı', 'ˆ', '˜', '¯', '˘', '˙', '˚', '¸', '˝', '˛', 'ˇ',
196	    ];
197	
198	    fn char_from_mac_roman(code: u8) -> char {
199	        if code < 128 { code as char } else { TABLE[(code - 128) as usize] }
200	    }
201	
202	    coded.iter().copied().map(char_from_mac_roman).collect()
203	}
204	
205	/// Trim style naming from a family name and fix bad names.
206	fn typographic_family(mut family: &str) -> &str {
207	    // Separators between names, modifiers and styles.
208	    const SEPARATORS: [char; 3] = [' ', '-', '_'];
209	
210	    // Modifiers that can appear in combination with suffixes.
211	    const MODIFIERS: &[&str] =
212	        &["extra", "ext", "ex", "x", "semi", "sem", "sm", "demi", "dem", "ultra"];
213	
214	    // Style suffixes.
215	    #[rustfmt::skip]
216	    const SUFFIXES: &[&str] = &[
217	        "normal", "italic", "oblique", "slanted",
218	        "thin", "th", "hairline", "light", "lt", "regular", "medium", "med",
219	        "md", "bold", "bd", "demi", "extb", "black", "blk", "bk", "heavy",
220	        "narrow", "condensed", "cond", "cn", "cd", "compressed", "expanded", "exp",
221	        "vf", "var", "variable",
222	    ];
223	
224	    // Trim spacing and weird leading dots in Apple fonts.
225	    family = family.trim().trim_start_matches('.');
226	
227	    // Lowercase the string so that the suffixes match case-insensitively.
228	    let lower = family.to_ascii_lowercase();
229	    let mut len = usize::MAX;
230	    let mut trimmed = lower.as_str();
231	
232	    // Trim style suffixes repeatedly.
233	    while trimmed.len() < len {
234	        len = trimmed.len();
235	
236	        // Find style suffix.
237	        let mut t = trimmed;
238	        let mut shortened = false;
239	        while let Some(s) = SUFFIXES.iter().find_map(|s| t.strip_suffix(s)) {
240	            shortened = true;
241	            t = s;
242	        }
243	
244	        if !shortened {
245	            break;
246	        }
247	
248	        // Strip optional separator.
249	        if let Some(s) = t.strip_suffix(SEPARATORS) {
250	            trimmed = s;
251	            t = s;
252	        }
253	
254	        // Also allow an extra modifier, but apply it only if it is separated it
255	        // from the text before it (to prevent false positives).
256	        if let Some(t) = MODIFIERS.iter().find_map(|s| t.strip_suffix(s))
257	            && let Some(stripped) = t.strip_suffix(SEPARATORS)
258	        {
259	            trimmed = stripped;
260	        }
261	    }
262	
263	    // Apply style suffix trimming.
264	    family = &family[..len];
265	
266	    family
267	}
268	
269	/// A compactly encoded set of codepoints.
270	///
271	/// The set is represented by alternating specifications of how many codepoints
272	/// are not in the set and how many are in the set.
273	///
274	/// For example, for the set `{2, 3, 4, 9, 10, 11, 15, 18, 19}`, there are:
275	/// - 2 codepoints not inside (0, 1)
276	/// - 3 codepoints inside (2, 3, 4)
277	/// - 4 codepoints not inside (5, 6, 7, 8)
278	/// - 3 codepoints inside (9, 10, 11)
279	/// - 3 codepoints not inside (12, 13, 14)
280	/// - 1 codepoint inside (15)
281	/// - 2 codepoints not inside (16, 17)
282	/// - 2 codepoints inside (18, 19)
283	///
284	/// So the resulting encoding is `[2, 3, 4, 3, 3, 1, 2, 2]`.
285	#[derive(Clone, Eq, PartialEq, Hash, Serialize, Deserialize)]
286	#[serde(transparent)]
287	pub struct Coverage(Vec<u32>);
288	
289	impl Coverage {
290	    /// Encode a vector of codepoints.
291	    pub fn from_vec(mut codepoints: Vec<u32>) -> Self {
292	        #[expect(
293	            clippy::stable_sort_primitive,
294	            reason = "`sort_unstable` hurts performance here. Compiling a 'Hello World!' \
295	            PDF with `--ignore-system-fonts` goes from 7.8ms to 9.1ms or +16%."
296	        )]
297	        codepoints.sort();
298	        codepoints.dedup();
299	
300	        let mut runs = Vec::new();
301	        let mut next = 0;
302	
303	        for c in codepoints {
304	            if let Some(run) = runs.last_mut().filter(|_| c == next) {
305	                *run += 1;
306	            } else {
307	                runs.push(c - next);
308	                runs.push(1);
309	            }
310	
311	            next = c + 1;
312	        }
313	
314	        Self(runs)
315	    }
316	
317	    /// Whether the codepoint is covered.
318	    pub fn contains(&self, c: u32) -> bool {
319	        let mut inside = false;
320	        let mut cursor = 0;
321	
322	        for &run in &self.0 {
323	            if (cursor..cursor + run).contains(&c) {
324	                return inside;
325	            }
326	            cursor += run;
327	            inside = !inside;
328	        }
329	
330	        false
331	    }
332	
333	    /// Iterate over all covered codepoints.
334	    pub fn iter(&self) -> impl Iterator<Item = u32> + '_ {
335	        let mut inside = false;
336	        let mut cursor = 0;
337	        self.0.iter().flat_map(move |run| {
338	            let range = if inside { cursor..cursor + run } else { 0..0 };
339	            inside = !inside;
340	            cursor += run;
341	            range
342	        })
343	    }
344	}
345	
346	impl Debug for Coverage {
347	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
348	        f.pad("Coverage(..)")
349	    }
350	}
351	
352	#[cfg(test)]
353	mod tests {
354	    use super::*;
355	
356	    #[test]
357	    fn test_trim_styles() {
358	        assert_eq!(typographic_family("Atma Light"), "Atma");
359	        assert_eq!(typographic_family("eras bold"), "eras");
360	        assert_eq!(typographic_family("footlight mt light"), "footlight mt");
361	        assert_eq!(typographic_family("times new roman"), "times new roman");
362	        assert_eq!(typographic_family("noto sans mono cond sembd"), "noto sans mono");
363	        assert_eq!(typographic_family("noto serif SEMCOND sembd"), "noto serif");
364	        assert_eq!(typographic_family("crimson text"), "crimson text");
365	        assert_eq!(typographic_family("footlight light"), "footlight");
366	        assert_eq!(typographic_family("Noto Sans"), "Noto Sans");
367	        assert_eq!(typographic_family("Noto Sans Light"), "Noto Sans");
368	        assert_eq!(typographic_family("Noto Sans Semicondensed Heavy"), "Noto Sans");
369	        assert_eq!(typographic_family("Familx"), "Familx");
370	        assert_eq!(typographic_family("Font Ultra"), "Font Ultra");
371	        assert_eq!(typographic_family("Font Ultra Bold"), "Font");
372	    }
373	
374	    #[test]
375	    fn test_coverage() {
376	        #[track_caller]
377	        fn test(set: &[u32], runs: &[u32]) {
378	            let coverage = Coverage::from_vec(set.to_vec());
379	            assert_eq!(coverage.0, runs);
380	
381	            let max = 5 + set.iter().copied().max().unwrap_or_default();
382	            for c in 0..max {
383	                assert_eq!(set.contains(&c), coverage.contains(c));
384	            }
385	        }
386	
387	        test(&[], &[]);
388	        test(&[0], &[0, 1]);
389	        test(&[1], &[1, 1]);
390	        test(&[0, 1], &[0, 2]);
391	        test(&[0, 1, 3], &[0, 2, 1, 1]);
392	        test(
393	            // {2, 3, 4, 9, 10, 11, 15, 18, 19}
394	            &[18, 19, 2, 4, 9, 11, 15, 3, 3, 10],
395	            &[2, 3, 4, 3, 3, 1, 2, 2],
396	        );
397	    }
398	
399	    #[test]
400	    fn test_coverage_iter() {
401	        let codepoints = vec![2, 3, 7, 8, 9, 14, 15, 19, 21];
402	        let coverage = Coverage::from_vec(codepoints.clone());
403	        assert_eq!(coverage.iter().collect::<Vec<_>>(), codepoints);
404	    }
405	}
